import{_ as e,o as a,c as r,ae as n}from"./chunks/framework.CSxHcPWC.js";const u=JSON.parse('{"title":"🛠️ The WealthFam Tech Stack","description":"","frontmatter":{},"headers":[],"relativePath":"technical/stack.md","filePath":"technical/stack.md"}'),i={name:"technical/stack.md"};function l(o,t,s,d,g,c){return a(),r("div",null,[...t[0]||(t[0]=[n('<h1 id="🛠️-the-wealthfam-tech-stack" tabindex="-1">🛠️ The WealthFam Tech Stack <a class="header-anchor" href="#🛠️-the-wealthfam-tech-stack" aria-label="Permalink to &quot;🛠️ The WealthFam Tech Stack&quot;">​</a></h1><p>WealthFam is built on a &quot;Local-First, AI-Augmented&quot; philosophy. Every technology in our stack is chosen for its performance, privacy characteristics, and developer experience.</p><hr><h2 id="🚀-backend-fastapi-python-3-10" tabindex="-1">🚀 Backend: FastAPI &amp; Python 3.10+ <a class="header-anchor" href="#🚀-backend-fastapi-python-3-10" aria-label="Permalink to &quot;🚀 Backend: FastAPI &amp; Python 3.10+&quot;">​</a></h2><p>We chose <strong>FastAPI</strong> as the central orchestrator for its modern features:</p><ul><li><strong>High Performance</strong>: Built on Starlette and Pydantic, it is one of the fastest Python frameworks available.</li><li><strong>Type Safety</strong>: Leveraging Python type hints for automatic validation and interactive API documentation (Swagger/OpenAPI).</li><li><strong>Asynchronous Support</strong>: Perfect for handling multiple concurrent ingestion streams (SMS, Email, Web).</li></ul><hr><h2 id="🦆-database-duckdb" tabindex="-1">🦆 Database: DuckDB <a class="header-anchor" href="#🦆-database-duckdb" aria-label="Permalink to &quot;🦆 Database: DuckDB&quot;">​</a></h2><p>WealthFam utilizes <strong>DuckDB</strong> for its primary data storage. DuckDB is an in-process SQL OLAP database management system.</p><ul><li><strong>Local-First Privacy</strong>: Your financial data stays in a single file on your machine or container, never shared unless explicitly synced.</li><li><strong>Extreme Speed</strong>: Optimized for analytical queries (e.g., &quot;Show me my spending by category over the last 12 months&quot;) with columnar execution.</li><li><strong>Zero Management</strong>: No server to install or maintain; it works as easily as SQLite but with modern performance.</li></ul><hr><h2 id="🎨-frontend-vue-3-material-3" tabindex="-1">🎨 Frontend: Vue 3 &amp; Material 3 <a class="header-anchor" href="#🎨-frontend-vue-3-material-3" aria-label="Permalink to &quot;🎨 Frontend: Vue 3 &amp; Material 3&quot;">​</a></h2><p>Our web interface is designed for clarity and responsiveness:</p><ul><li><strong>Vue 3 (Composition API)</strong>: Provides a clean, reactive architecture for complex financial dashboards.</li><li><strong>Vite</strong>: The next-generation frontend tool that ensures near-instant development starts and builds.</li><li><strong>Material Design 3 (M3)</strong>: We strictly follow M3 principles to ensure the UI is accessible, beautiful, and feels native on every device.</li><li><strong>Tailwind CSS</strong>: For high-fidelity, utility-first styling that doesn&#39;t bloat the bundle.</li></ul><hr><h2 id="📱-mobile-flutter" tabindex="-1">📱 Mobile: Flutter <a class="header-anchor" href="#📱-mobile-flutter" aria-label="Permalink to &quot;📱 Mobile: Flutter&quot;">​</a></h2><p>The <strong>WealthFam Mobile</strong> app (Android) is built with <strong>Flutter</strong>:</p><ul><li><strong>Native Performance</strong>: Compiles to ARM machine code for smooth 60fps animations.</li><li><strong>Native Integration</strong>: Essential for our background SMS listeners and device hashing capabilities.</li><li><strong>Single Codebase</strong>: Allows us to maintain a consistent experience if we expand to iOS in the future.</li></ul><hr><h2 id="🧠-ai-google-gemini-pro" tabindex="-1">🧠 AI: Google Gemini Pro <a class="header-anchor" href="#🧠-ai-google-gemini-pro" aria-label="Permalink to &quot;🧠 AI: Google Gemini Pro&quot;">​</a></h2><p>For unstructured data parsing (like messy credit card SMS or non-standard bank emails), we use <strong>Gemini Pro</strong>:</p><ul><li><strong>Logical Reasoning</strong>: Gemini excels at extracting structured JSON from natural language financial alerts.</li><li><strong>Privacy-Conscious</strong>: We only send the minimum required text for parsing; no identifying PII is sent to the model.</li></ul><hr><table tabindex="0"><thead><tr><th style="text-align:left;">Layer</th><th style="text-align:left;">Technology</th><th style="text-align:left;">Role</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Orchestration</strong></td><td style="text-align:left;"><a href="https://fastapi.tiangolo.com/" target="_blank" rel="noreferrer">FastAPI</a></td><td style="text-align:left;">API Gateways &amp; Business Logic</td></tr><tr><td style="text-align:left;"><strong>Persistence</strong></td><td style="text-align:left;"><a href="https://duckdb.org/" target="_blank" rel="noreferrer">DuckDB</a></td><td style="text-align:left;">Precision Ledger &amp; Analytics</td></tr><tr><td style="text-align:left;"><strong>Logic Engine</strong></td><td style="text-align:left;"><a href="https://www.python.org/" target="_blank" rel="noreferrer">Python 3.10+</a></td><td style="text-align:left;">Core Parsing &amp; Merging</td></tr><tr><td style="text-align:left;"><strong>Interface</strong></td><td style="text-align:left;"><a href="https://vuejs.org/" target="_blank" rel="noreferrer">Vue.js 3</a></td><td style="text-align:left;">Web Dashboard</td></tr><tr><td style="text-align:left;"><strong>Mobile</strong></td><td style="text-align:left;"><a href="https://flutter.dev/" target="_blank" rel="noreferrer">Flutter</a></td><td style="text-align:left;">Real-time SMS Ingestion</td></tr><tr><td style="text-align:left;"><strong>Intelligence</strong></td><td style="text-align:left;"><a href="https://deepmind.google/technologies/gemini/" target="_blank" rel="noreferrer">Gemini AI</a></td><td style="text-align:left;">Unstructured Text Parsing</td></tr><tr><td style="text-align:left;"><strong>Styling</strong></td><td style="text-align:left;"><a href="https://tailwindcss.com/" target="_blank" rel="noreferrer">Tailwind CSS</a></td><td style="text-align:left;">Material 3 Implementation</td></tr></tbody></table><hr><div align="center"> *Engineering Excellence · Local Isolation · Precision Accuracy* </div>',26)])])}const f=e(i,[["render",l]]);export{u as __pageData,f as default};

